module mouth_cut() {
    translate([0,0,-1])
        linear_extrude(height=T+2, convexity=10)
            polygon(points=concat(
                [[0,0]],
                [for (a=[105:2.5:255]) [50*cos(a), 50*sin(a)]]
            ));
