module arm_2d(x1, x2) {
    hull() {
        translate([x1, -ARM_W/2+1]) circle(r=1, $fn=32);
        translate([x1,  ARM_W/2-1]) circle(r=1, $fn=32);
        translate([x2, -ARM_W/2+1]) circle(r=1, $fn=32);
        translate([x2,  ARM_W/2-1]) circle(r=1, $fn=32);
    }
}

module neck_2d() {
    hull() {
        translate([NECK_X1, -NECK_W/2+1]) circle(r=1, $fn=32);
        translate([NECK_X1,  NECK_W/2-1]) circle(r=1, $fn=32);
        translate([NECK_X2, -NECK_W/2+1]) circle(r=1, $fn=32);
        translate([NECK_X2,  NECK_W/2-1]) circle(r=1, $fn=32);
    }
}

