}

module tail_2d() {
    polygon(points=[
        [R_SEP, -BODY_W/2],
        [16.0,  -BODY_W/2],
        [21.0,  -6.0],
        [L,      0.0],
        [21.0,   6.0],
        [16.0,   BODY_W/2],
        [R_SEP,  BODY_W/2]
    ]);
